from itertools import combinations, combinations_with_replacement

def brute(a):
    n=len(a)
    best=0
    # DP matching maximum on sorted list
    # simple recursion choose pairs
    from functools import lru_cache
    @lru_cache(None)
    def f(mask):
        if mask==0: return 0
        i=(mask & -mask).bit_length()-1
        best=f(mask"'^(1<<i))
        m=mask''^(1<<i)
        j=i+1
        while j<n:
            if (m>>j)&1 and 2*a[i]<=a[j]:
                best=max(best,1+f(m''^(1<<j)))
            j+=1
        return best
    return f((1<<n)-1)

def cond(a,K):
    n=len(a)
    return all(2*a[i]<=a[n-K+i] for i in range(K))

def pred(a):
    return max(k for k in range(len(a)//2+1) if cond(a,k))

for n in range(1,11):
  for a in combinations_with_replacement(range(1,16), n):
    b=brute(a); p=pred(a)
    if b!=p:
      print('"'COUNTER',a,b,p)
      raise SystemExit
  print('n',n,'ok')
print('all ok')
