from collections import deque
from itertools import product
from random import randint,seed
MOD=998244353

def solve1(n,m,A):
    indeg=[0]*n
    for v in range(n): indeg[A[v]]+=1
    dq=deque(v for v in range(n) if indeg[v]==0)
    dp=[[1]*(m+1) for _ in range(n)]
    order=[]
    while dq:
        v=dq.popleft();order.append(v)
        p=A[v]; indeg[p]-=1
        if indeg[p]==0:dq.append(p)
    for v in order:
        arr=dp[v];run=0
        for y in range(1,m+1):
            run+=arr[y]
            if run>=MOD:run-=MOD
            arr[y]=run
        par=dp[A[v]]
        for y in range(1,m+1):
            par[y]=par[y]*arr[y]%MOD
    vis=[False]*n; ans=1
    for s in range(n):
        if indeg[s]>0 and not vis[s]:
            cyc=[];u=s
            while not vis[u]:
                vis[u]=True;cyc.append(u);u=A[u]
            acc=[1]*(m+1)
            for v in cyc:
                arr=dp[v]
                for y in range(1,m+1):
                    acc[y]=acc[y]*arr[y]%MOD
            tot=sum(acc[1:])%MOD
            ans=ans*tot%MOD
    return ans

def brute(n,m,A):
    c=0
    for x in product(range(1,m+1),repeat=n):
        if all(x[i]<=x[A[i]] for i in range(n)):c+=1
    return c%MOD
